<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Size Shift</title>
  <style>
    body { margin:0; background:#0a0a0f; color:#e6e6f0; font-family:ui-sans-serif,system-ui,sans-serif; }
    .game-header { padding:12px 16px; border-bottom:1px solid #1d1d2a; }
    .game-header h1 { margin:0; font-size:18px; color:#7df9ff; }
    .game-header .game-description { margin:4px 0; color:#a5a5b8; }
    .game-header .game-controls { margin:4px 0; padding-left:18px; color:#c8c8d8; }
    main { display:flex; flex-direction:column; align-items:center; padding:16px; }
    canvas { background:#0f1320; border:1px solid #2a2f44; }
    .game-restart { margin-top:10px; padding:8px 14px; background:#1c2030; color:#7df9ff; border:1px solid #2a2f44; cursor:pointer; }
    .game-restart:hover { background:#232842; }
  </style>
</head>
<body>
  <header class="game-header">
    <h1>Size Shift</h1>
    <p class="game-description">Tap to toggle the dot between a small and a large size; the tiny form slips through narrow gaps while the large form covers broader openings and can crush small obstacles, forcing you to switch sizes at the right moments.</p>
    <ul class="game-controls">
      <li>Tap or click to toggle size</li>
      <li>Press R or click Restart</li>
    </ul>
  </header>
  <main>
    <canvas id="game" width="800" height="600"></canvas>
    <button id="restart" class="game-restart" type="button">Restart</button>
  </main>
  <script>
    // === CONFIG =============================================================
    // (future configuration constants)

    // === STATE ==============================================================
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const restartBtn = document.getElementById('restart');

    // Placeholder game state
    let phase = 'menu';
    let score = 0;
    let player = { x: canvas.width / 2, y: canvas.height / 2 };
    let keys = new Set();

    // === RESET ==============================================================
    function reset() {
      // Placeholder reset logic
      phase = 'playing';
      score = 0;
      player = { x: canvas.width / 2, y: canvas.height / 2 };
      publishState();
    }

    // === LOOP / UPDATE =====================================================
    let lastTime = performance.now();
    let loopId = null;
    function startLoop() {
      if (loopId !== null) cancelAnimationFrame(loopId);
      function tick(now) {
        try {
          // placeholder update
          const dt = Math.min((now - lastTime) / 1000, 0.1);
          lastTime = now;
        } catch (e) { console.error('loop error', e); }
        loopId = requestAnimationFrame(tick);
      }
      loopId = requestAnimationFrame(tick);
    }

    // === RENDER ============================================================
    function render() {
      // placeholder render: clear canvas
      ctx.fillStyle = '#0f1320';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    // === INPUT ==============================================================
    document.addEventListener('keydown', (ev) => {
      if (ev.key === 'r' || ev.key === 'R') { reset(); return; }
      keys.add(ev.key);
    });
    document.addEventListener('keyup', (ev) => { keys.delete(ev.key); });
    restartBtn.addEventListener('click', reset);

    // === AUDIO ==============================================================
    // Placeholder audio function
    function beep() {}

    // === OBSERVABLE CONTRACT ==============================================
    function publishState() {
      window.__game = {
        state: phase === 'playing' ? 'playing' : (phase === 'menu' ? 'menu' : 'gameover'),
        score,
        player: {
          x: player.x,
          y: player.y,
          visible: true,
        },
        objective: 'Tap to toggle size and navigate through obstacles.',
      };
    }

    // === BOOT ==============================================================
    reset();
    startLoop();
    render();
    publishState();
  </script>
</body>
</html>

